func:
// Dropped server-side mode filtering (?mode=APT etc.) -- never confirmed
// that query parameter actually works; SatNOGS' own filter API has a
// documented history of silently returning nothing for filters beyond
// status=. Fetching all active transmitters instead and filtering on the
// confirmed real 'mode' field client-side in the merge step.
var msgs = [{
    url: 'https://db.satnogs.org/api/transmitters/?status=active&format=json',
    method: 'GET'
}];

node.status({ fill: 'blue', shape: 'dot', text: 'querying all active transmitters' });
return [msgs];

// Confirmed real SatNOGS mode strings for weather-image downlink,
// filtered here instead of via an unconfirmed query parameter.
var IMAGERY_MODES = ['APT', 'LRPT', 'HRPT', 'HRIT'];

var idSet = flow.get('wx_imagery_id_set') || {};
var radioMap = flow.get('wx_radio') || {};
var arr = Array.isArray(msg.payload) ? msg.payload : [];

arr.forEach(function (t) {
    if (!t || !t.norad_cat_id) return;
    if (IMAGERY_MODES.indexOf(t.mode) === -1) return; // not a confirmed imagery mode

    idSet[t.norad_cat_id] = true;

    if (!t.downlink_low) return;
    var freqStr = t.mode + ' ' + (t.downlink_low / 1e6).toFixed(3) + ' MHz';

    var list = radioMap[t.norad_cat_id] || [];
    if (list.indexOf(freqStr) === -1) { list.push(freqStr); }
    radioMap[t.norad_cat_id] = list;
});

flow.set('wx_imagery_id_set', idSet);
flow.set('wx_radio', radioMap);

var ids = Object.keys(idSet).map(function (s) { return parseInt(s, 10); });
flow.set('wx_imagery_ids', ids);
node.status({ fill: 'blue', shape: 'dot', text: ids.length + ' imagery-downlink satellites' });
return null;

var sourceName = 'spacetrack-wx';
var cooldownMinutes = 60;
var key = 'circuitBreaker_' + sourceName;
var state = flow.get(key) || { open: false, failCount: 0, openedAt: 0 };

if (state.open) {
    var elapsedMin = (Date.now() - state.openedAt) / 60000;
    if (elapsedMin < cooldownMinutes) {
        node.status({ fill: 'red', shape: 'ring', text: sourceName + ': OPEN (' + Math.round(cooldownMinutes - elapsedMin) + 'm left)' });
        return null;
    }
    node.status({ fill: 'yellow', shape: 'dot', text: sourceName + ': testing recovery' });
}

msg._circuitBreakerSource = sourceName;
return msg;

var user = env.get('SPACETRACK_USER');
var pass = env.get('SPACETRACK_PASS');
if (!user || !pass) {
    node.status({ fill: 'red', shape: 'ring', text: 'Set SPACETRACK_USER/PASS in tab env vars' });
    return null;
}
msg.payload = 'identity=' + encodeURIComponent(user) + '&password=' + encodeURIComponent(pass);
msg.headers = { 'Content-Type': 'application/x-www-form-urlencoded' };
return msg;

var setCookie = msg.headers && msg.headers['set-cookie'];
if (!setCookie || !setCookie.length) {
    node.status({ fill: 'red', shape: 'ring', text: 'login failed -- no Set-Cookie received' });
    node.error('Space-Track login: no Set-Cookie header in response (check SPACETRACK_USER/PASS)', msg);
    return null;
}
var cookieHeader = setCookie.map(function (c) { return c.split(';')[0]; }).join('; ');
flow.set('spacetrack_session_cookie', cookieHeader);
node.status({ fill: 'green', shape: 'dot', text: 'session cookie captured' });
return msg;

var NORAD_IDS = flow.get('wx_imagery_ids') || [];
var CHUNK_SIZE = 300;

if (!NORAD_IDS.length) {
    node.status({ fill: 'grey', shape: 'ring', text: 'waiting for first SatNOGS imagery refresh' });
    return null;
}

var cookie = flow.get('spacetrack_session_cookie');
if (!cookie) {
    node.status({ fill: 'red', shape: 'ring', text: 'no session cookie -- login step failed upstream' });
    return null;
}

var chunks = [];
for (var i = 0; i < NORAD_IDS.length; i += CHUNK_SIZE) {
    chunks.push(NORAD_IDS.slice(i, i + CHUNK_SIZE));
}

var msgs = chunks.map(function (chunk) {
    var queryUrl = 'https://www.space-track.org/basicspacedata/query/class/gp/NORAD_CAT_ID/' +
        chunk.join(',') + '/orderby/NORAD_CAT_ID/format/json';
    return {
        url: queryUrl,
        method: 'GET',
        headers: { Cookie: cookie },
        _circuitBreakerSource: msg._circuitBreakerSource
    };
});

node.status({ fill: 'blue', shape: 'dot', text: 'querying ' + NORAD_IDS.length + ' IDs in ' + msgs.length + ' request(s)' });
return [msgs];

var ERROR_CODES = [301, 400, 401, 403, 404, 429, 500, 502, 503, 504];
var TRIP_THRESHOLD = 1;

var sourceName = msg._circuitBreakerSource || node.id;
var key = 'circuitBreaker_' + sourceName;
var state = flow.get(key) || { open: false, failCount: 0, openedAt: 0 };

var code = msg.statusCode;
var bodyLooksLikeError = typeof msg.payload === 'string' &&
    /error|invalid|denied/i.test(msg.payload.slice(0, 300));
var isError = ERROR_CODES.indexOf(code) !== -1 || bodyLooksLikeError;

if (isError) {
    state.failCount = (state.failCount || 0) + 1;
    if (state.failCount >= TRIP_THRESHOLD) {
        state.open = true;
        state.openedAt = Date.now();
        state.lastError = { code: code, at: new Date().toISOString() };
        flow.set(key, state);
        node.error('CIRCUIT BREAKER TRIPPED: ' + sourceName + ' returned HTTP ' + code + ' -- further queries blocked', msg);
        node.status({ fill: 'red', shape: 'dot', text: sourceName + ': TRIPPED (HTTP ' + code + ')' });
        return [null, { payload: { sourceName: sourceName, statusCode: code, failCount: state.failCount, timestamp: new Date().toISOString() } }];
    }
    flow.set(key, state);
    node.warn(sourceName + ': error ' + code + ' (' + state.failCount + '/' + TRIP_THRESHOLD + ' before trip)');
    return [null, null];
}

if (state.failCount > 0 || state.open) {
    node.status({ fill: 'green', shape: 'dot', text: sourceName + ': recovered' });
}
flow.set(key, { open: false, failCount: 0, openedAt: 0 });
return [msg, null];

var arr = Array.isArray(msg.payload) ? msg.payload : [];
var newSats = [];
arr.forEach(function (o) {
    if (o && o.TLE_LINE1 && o.TLE_LINE2) {
        newSats.push({
            name: o.OBJECT_NAME || ('NORAD ' + o.NORAD_CAT_ID),
            line1: o.TLE_LINE1,
            line2: o.TLE_LINE2,
            noradId: String(o.NORAD_CAT_ID),
            country: o.COUNTRY_CODE || 'UNKNOWN'
        });
    }
});

// Purge anything no longer in the current SatNOGS imagery ID list --
// prevents satellites that dropped out (transmitter went inactive)
// from lingering in wx_sats forever.
var currentIds = {};
(flow.get('wx_imagery_ids') || []).forEach(function (id) { currentIds[String(id)] = true; });

var existing = flow.get('wx_sats') || [];
var map = {};
existing.forEach(function (s) { if (currentIds[s.noradId]) { map[s.noradId] = s; } });
newSats.forEach(function (s) { map[s.noradId] = s; });
var merged = Object.keys(map).map(function (k) { return map[k]; });

flow.set('wx_sats', merged);
node.status({ fill: 'blue', shape: 'dot', text: merged.length + ' objects cached' });
return null;

var channelName = 'SystemAlerts';
var markerLat = 36.1627; var markerLon = -86.7816;
var staleMinutes = 60;

function esc(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }

var a = msg.payload;
var now = new Date(); var start = now.toISOString();
var stale = new Date(now.getTime() + staleMinutes * 60000).toISOString();
var uid = 'circuit-alert-' + a.sourceName;
var remarks = 'CIRCUIT BREAKER TRIPPED | Source: ' + a.sourceName + ' | HTTP ' + a.statusCode +
    ' | Failures: ' + a.failCount + ' | Since: ' + a.timestamp + ' | Further queries blocked until cooldown expires';
var cot = '<?xml version="1.0" encoding="UTF-8"?>' +
    '<event version="2.0" uid="' + esc(uid) + '" type="b-m-p-s-m" how="m-g" ' +
    'time="' + start + '" start="' + start + '" stale="' + stale + '">' +
    '<point lat="' + markerLat + '" lon="' + markerLon + '" hae="0" ce="9999999.0" le="9999999.0"/>' +
    '<detail><contact callsign="ALERT: ' + esc(a.sourceName) + '"/><color value="-65536"/>' +
    '<remarks>' + esc(remarks) + '</remarks><marti><dest name="' + esc(channelName) + '"/></marti></detail></event>';
msg.payload = cot;
return msg;

var sourceName = msg.topic;
if (!sourceName) { node.warn('Set the inject node topic to the sourceName to reset'); return null; }
flow.set('circuitBreaker_' + sourceName, { open: false, failCount: 0, openedAt: 0 });
node.warn('Circuit breaker manually cleared for: ' + sourceName);
node.status({ fill: 'green', shape: 'dot', text: sourceName + ': manually cleared' });
return null;

var staleSeconds = 120;

var FRIENDLY = ['US','UK','FR','GERMANY','GER','IT','CANADA','CA',
    'SPAIN','NETH','NETHERLANDS','BEL','NORWAY','DEN','POLAND','TURK',
    'PORTUGAL','GREECE','CZCH','ROMANIA','HUNGARY','SVK','HRV','JPN','JAPAN','AUS','AUSTRALIA',
    'ROK','SKOR','SKOREA','NZ','ESA','EUME','ISRA','MEX','RP','JOR','THAI','SAUD','SWTZ','IND','ARGN','INDO','MALA','BRAZ','SAFR','ISS','AB'];
var HOSTILE = ['CIS','RUSSIA','SU','PRC','CHN','CHINA','PRK','NKOR','NORTH KOREA','CUBA','VTNM','VIETNAM','LAOS'];

var sats = flow.get('wx_sats') || [];
if (!sats.length) {
    node.status({ fill: 'grey', shape: 'ring', text: 'waiting for first Space-Track refresh' });
    return null;
}

var now = new Date();
var startIso = now.toISOString();
var staleIso = new Date(now.getTime() + staleSeconds * 1000).toISOString();
var gmst = satellite.gstime(now);

var msgs = []; var errors = 0; var staleTle = 0;
// Skip satellites whose element set is older than this: they are dead / re-entered
// (Space-Track stops updating them) and propagate to wrong positions or fail.
var MAX_TLE_AGE_DAYS = 30;
var radioAll = flow.get('wx_radio') || {};
sats.forEach(function (s) {
    try {
        var satrec = satellite.twoline2satrec(s.line1, s.line2);
        var epochMs = (satrec.jdsatepoch + (satrec.jdsatepochF || 0) - 2440587.5) * 86400000;
        if (!isFinite(epochMs) || (now.getTime() - epochMs) > MAX_TLE_AGE_DAYS * 86400000) { staleTle++; return; }
        var pv = satellite.propagate(satrec, now);
        if (!pv || !pv.position) { errors++; return; }
        var geo = satellite.eciToGeodetic(pv.position, gmst);
        var lat = satellite.degreesLat(geo.latitude);
        var lon = satellite.degreesLong(geo.longitude);
        var altKm = geo.height;

        var cc = (s.country || 'UNKNOWN').toUpperCase();
        var aff = 'u';
        if (FRIENDLY.indexOf(cc) !== -1) { aff = 'f'; }
        else if (HOSTILE.indexOf(cc) !== -1) { aff = 'h'; }

        var funcLetter = 'S';
        var cotExt = '';
        var affLetter = (aff === 'f') ? 'F' : (aff === 'h') ? 'H' : 'U';
        var cotType = 'a-' + aff + '-P-' + funcLetter + cotExt;
        var sidc = 'S' + affLetter + 'P*' + funcLetter + '-----*****';
        var uid = 'sat-' + s.noradId;

        var radioList = radioAll[s.noradId];
        var radio = (radioList && radioList.length) ? radioList.join(' | ') : null;
        var remarks = 'NORAD ' + s.noradId + ' | Owner: ' + cc + ' | Alt: ' + altKm.toFixed(1) + ' km | Name: ' + s.name +
            (radio ? ' | Imagery: ' + radio : '');

        var cot = '<?xml version="1.0" encoding="UTF-8"?>' +
            '<event version="2.0" uid="' + uid + '" type="' + cotType + '" how="m-g" ' +
            'time="' + startIso + '" start="' + startIso + '" stale="' + staleIso + '">' +
            '<point lat="' + lat.toFixed(6) + '" lon="' + lon.toFixed(6) + '" hae="' + (altKm * 1000).toFixed(0) + '" ce="9999999.0" le="9999999.0"/>' +
            '<detail>' +
            '<contact callsign="' + s.name.replace(/&/g,'&amp;').replace(/</g,'&lt;') + '"/>' +
            '<remarks>' + remarks.replace(/&/g,'&amp;').replace(/</g,'&lt;') + '</remarks>' +
            '<milsym id="' + sidc + '"/>' +
            '<milicon id="' + sidc + '"/>' +
            '</detail>' +
            '</event>';

        msgs.push({ payload: cot });
    } catch (e) { errors++; }
});

node.status({ fill: 'green', shape: 'dot', text: msgs.length + ' sats emitted' + (staleTle ? (', ' + staleTle + ' skipped (TLE > ' + MAX_TLE_AGE_DAYS + 'd old)') : '') + (errors ? (', ' + errors + ' errors') : '') });
return [msgs];

var sats = flow.get('wx_sats') || [];
var radioAll = flow.get('wx_radio') || {};
var breaker = flow.get('circuitBreaker_spacetrack-wx') || {};
msg.payload = JSON.stringify({
    imagery_ids_count: (flow.get('wx_imagery_ids') || []).length,
    cached_sats_count: sats.length,
    breaker_open: !!breaker.open,
    breaker_last_error: breaker.lastError || null,
    objects: sats.map(function (s) {
        return { name: s.name, noradId: s.noradId, country: s.country, radio: radioAll[s.noradId] || [] };
    })
}, null, 2);
msg.headers = { 'Content-Type': 'application/json' };
return msg;
